mapper.select:
SELECT b.task_result_id, b.device_id, b.device_name, g.cruise_data_id, g.cruise_result_id, b.instance_id, b.cruise_time, f.real_code, g.cruise_type, h.dict_note as cruise_type_name, g.result_num, g.cruise_result, j.dict_note as cruise_result_name, g.cruise_abnormal, p.dict_note as abnormal_type, g.evaluation_state, i.dict_note as evaluation_state_name, g.check_user, g.check_date, g.picpath as pic_path, g.identify_result, g.identify_state, g.person_check, b.instance_name FROM t_cruise_result a LEFT JOIN t_cruise_task_result_detail b on a.task_result_id = b.task_result_id LEFT JOIN t_cruise_point_instance e on b.instance_id = e.instance_id LEFT JOIN t_std_device_attr f on f.device_id = b.device_id LEFT JOIN t_cruise_data_result g on g.cruise_result_id = b.cruise_result_id LEFT JOIN t_dict_business h on h.dict_code = g.cruise_type LEFT JOIN t_dict_business i on i.dict_code = g.evaluation_state LEFT JOIN t_dict_business j on j.dict_code = g.cruise_result LEFT JOIN t_dict_business p ON p.dict_code = g.cruise_abnormal WHERE 1 = 1 and b.task_result_id = #{taskResultId,jdbcType=VARCHAR}
and b.device_name like concat ('%',#{deviceName,jdbcType=VARCHAR},'%')
and g.cruise_type = #{cruiseType, jdbcType=INTEGER}
and g.cruise_abnormal = #{cruiseAbnormal, jdbcType=INTEGER} ORDER BY cruise_time DESC

mapper.update:
update t_cruise_result a 
a.check_user = #{checkUserName, jdbcType=VARCHAR},
a.check_date = #{checkDate, jdbcType=TIMESTAMP}

where a.task_result_id = #{taskResultId, jdbcType=VARCHAR}

UPDATE t_warn_info a 
 a.if_warn_disable = 1

WHERE
a.task_id = #{taskId, jdbcType=VARCHAR}
and a.instance_id = #{instanceId,jdbcType = BIGINT}

